6:export function newApiToken(workspaceId: string, pepper: string) {
7:  const kid = randomBytes(12).toString("hex");
8:  const secret = randomBytes(32).toString("base64url");
9:  return { kid, plaintext: `sg_${kid}.${secret}`, hash: agentHash("token", [workspaceId, secret], pepper) };
