150	async function write(p: AgentPrincipal, tool: ToolName, raw: unknown): Promise<unknown> {
151	  requireAgentPermission(p, tool === "draft_incident_update" ? "incidents:draft" : "monitors:write");
152	  const input = inputs[tool].parse(raw) as {request_id:string};
153	  const hash = fingerprint(tool,input);
154	  const prior = await db().from("agent_requests").select("input_hash,tool,result").eq("workspace_id",p.workspace.id).eq("actor",p.actor).eq("request_id",input.request_id).maybeSingle();
155	  if(prior.error) dbFailure(prior.error);
156	  if(prior.data) {
157	    if(prior.data.input_hash !== hash || prior.data.tool !== tool) throw new AgentError(409,"request_conflict","That request_id was already used with different inputs.");
158	    return writeResult(tool,prior.data.result);
159	  }
160	  let payload: unknown; let notCreated: string[] = [];
161	  const budget = () => spendAgentBudget(agentHash("network-tests",p.workspace.id,env().API_TOKEN_PEPPER),6);
162	  if(tool === "create_monitor") {
163	    const a = inputs.create_monitor.parse(input);
164	    await own(p,"app",a.app);
165	    const row = agentMonitorRow(a);
166	    await budget();
167	    const prepared = await prepareMonitor(p,row,true);
168	    payload = {app:a.app,monitor:prepared.row,first_check:prepared.first}; notCreated = [row.type];
169	  } else if(tool === "provision_app") {
170	    const a = inputs.provision_app.parse(input); const url = normalizeAppUrl(a.url);
171	    // URL parsing and address refusal happen even for an existing app.
172	    const appId = `app_${"0".repeat(24)}`;
173	    const drafts = [agentMonitorRow({ request_id:a.request_id,app:appId,type:"http",target:url,config:{},name:"Website" })];
174	    const skipped: {item:string;reason:string}[] = [];
175	    for(const cron of a.crons_from ?? []) drafts.push(agentMonitorRow({request_id:a.request_id,app:appId,type:"heartbeat",name:cron.name,target:cron.name,config:{schedule:cron.schedule,tz:cron.tz}}));
176	    if(a.supabase_url && a.supabase_key) drafts.push(agentMonitorRow({request_id:a.request_id,app:appId,type:"supabase",target:a.supabase_url,config:{key:a.supabase_key}}));
177	    else if(a.supabase_url || a.supabase_key) skipped.push({item:"supabase",reason:"Provide both supabase_url and its publishable key to create the health check."});
178	    if(a.stripe_key && a.stripe_endpoints?.length) drafts.push(agentMonitorRow({request_id:a.request_id,app:appId,type:"stripe",target:"https://api.stripe.com",config:{key:a.stripe_key,endpoints:a.stripe_endpoints}}));
179	    else if(a.stripe_key || a.stripe_endpoints) skipped.push({item:"stripe",reason:"Provide both a restricted key and the webhook endpoint ids to watch."});
180	    if(a.mcp_url) skipped.push({item:"mcp",reason:"MCP server monitors are Coming soon."});
181	    if(a.status_domain) skipped.push({item:"status_domain",reason:"Custom-domain setup belongs to the separate status-edge stage. The standard status page is available."});
182	    await budget();
183	    const prepared = await Promise.all(drafts.map(row=>prepareMonitor(p,row)));
184	    // The transaction chooses an unused default while holding the workspace lock.
185	    // An explicit name stays exact so a collision is a refusal, not a silent rename.
186	    payload = { url,name:a.name ?? null,name_base:new URL(url).hostname,slug:`app-${randomBytes(12).toString("hex")}`,monitors:prepared.map(x=>x.row),skipped };
187	    notCreated = ["app","status page",...drafts.map(r=>r.type)];
188	  } else if(tool === "pause") {
189	    const a = inputs.pause.parse(input);
190	    if(a.app) await own(p,"app",a.app); else await own(p,"monitor",a.monitor!);
191	    payload = a;
192	  } else {
193	    const a = inputs.draft_incident_update.parse(input); await own(p,"incident",a.incident); payload = a;
194	  }
195	  const L = p.entitlements.limits;
196	  const {data,error} = await db().rpc("agent_write",{p_workspace_id:p.workspace.id,p_actor:p.actor,p_client:p.client,p_scope:p.scope,p_tool:tool,p_request_id:input.request_id,p_input_hash:hash,p_payload:payload as Json,
197	    p_limits:{...L,perHost:L.perHost === "fair use" ? L.monitors : L.perHost,supabaseMonitors:L.supabaseMonitors === "cap" ? L.monitors : L.supabaseMonitors,minInterval:L.httpIntervalMin*60} as Json});
198	  if(error) dbFailure(error,notCreated);
199	  return writeResult(tool,data);
200	}
201	function writeResult(tool: ToolName, raw: Json): unknown {
202	  const r = record(raw);
203	  if(tool === "draft_incident_update") return {draft:r.draft,approval_url:new URL(`/app/incidents/${r.incident}`,env().APP_URL).href,published:false};
204	  if(tool !== "provision_app") return r;
205	  const receipt = z.object({app:z.string(),created:z.boolean(),monitors:z.array(z.object({id:z.string(),name:z.string(),type:z.string()})),heartbeats:z.array(z.object({monitor:z.string(),name:z.string(),sealed:z.string()})),slug:z.string(),skipped:z.array(z.object({item:z.string(),reason:z.string()}))}).parse(r);
206	  return {...receipt,slug:undefined,monitors:receipt.monitors.map(m=>({...m,name:mask(m.name)})),heartbeats:receipt.heartbeats.map(h=>{
207	    const url = openHeartbeat(h.sealed,h.monitor); if(!url) throw new AgentError(503,"temporarily_unavailable","A created heartbeat credential could not be opened. Try again later.");
208	    return {monitor:h.monitor,name:mask(h.name),url};
209	  }),status_page_url:new URL(`/s/${receipt.slug}`,env().APP_URL).href,cname:null};
210	}
